var TYPE=require("../../tokenizer").TYPE,HASH=TYPE.Hash;module.exports={name:"IdSelector",structure:{name:String},parse:function(){var t=this.scanner.tokenStart;return this.eat(HASH),{type:"IdSelector",loc:this.getLocation(t,this.scanner.tokenStart),name:this.scanner.substrToCursor(t+1)}},generate:function(t){this.chunk("#"),this.chunk(t.name)}};